 q.result['lastPrintAttempt']={'name':name,'events':q.ev('__printEvents'),'destinationFiles':[p.name for p in dest.iterdir()],'buttonPosition':point,'focus':q.ev('({visibility:document.visibilityState,hasFocus:document.hasFocus()})')};q.save();assert len(fresh)==1 and stable>=3,'Native PDF did not finish';target=dest/(name+'.pdf');fresh[0].rename(target);doc=pymupdf.open(target);text='\n'.join(p.get_text()for p in doc);events=q.ev('__printEvents');q.check('before'in events and'after'in events,name+' native beforeprint / afterprint');q.check('SIMULADOR LOCAL'not in text and'Controle do host'not in text,name+' child output only, without iframe host');q.check(all(abs(p.rect.width-595.3)<2 and abs(p.rect.height-841.9)<2 for p in doc),name+' A4 paper');overflow=[]
